    "s2-2-2-main-theme-permutation": {
      "id": "s2-2-2-main-theme-permutation",
      "title": "排列",
      "updatedAt": "2026-05-08T09:45:09+08:00",
      "variants": [
        {
          "id": "editable",
          "label": "可修改版",
          "sections": [
            {
              "type": "table",
              "headers": [
                "重點",
                "整理"
              ],
              "rows": [
                [
                  "排列在乎順序",
                  "選出同樣幾個物件，但順序不同，就算不同排列。"
                ],
                [
                  "從 $n$ 個不同物中取 $m$ 個排列",
                  "\\(P_m^n=\\frac{n!}{(n-m)!}\\)。"
                ],
                [
                  "全排列",
                  "若 \\(m=n\\)，共有 \\(n!\\) 種。"
                ],
                [
                  "相鄰問題",
                  "把必須黏在一起的物件先視為一個整體，再排列。"
                ],
                [
                  "不相鄰問題",
                  "通常先排其他物件，再把指定物件插入空位。"
                ],
                [
                  "固定次序問題",
                  "若幾個物件雖然要黏在一起，但內部順序固定，整體內部就不用再乘排列數。"
                ],
                [
                  "有重複物件時",
                  "若總共有 \\(n\\) 個物件，其中某些種類重複，排列數是 \\(\\frac{n!}{m_1!m_2!\\cdots m_k!}\\)。"
                ],
                [
                  "可重複取用時",
                  "每一個位置都有 \\(n\\) 種選擇，共 \\(m\\) 個位置，則方法數是 \\(n^m\\)。"
                ],
                [
                  "錯排問題",
                  "要求每個人都不能回到原位時，常要用容斥原理。"
                ],
                [
                  "解題提醒",
                  "只要順序會影響結果，就要優先往排列方向想。"
                ]
              ]
            }
          ]
        },
        {
          "id": "original",
          "label": "原稿版",
          "sections": [
            {
              "type": "pdf-page",
              "src": "exports/main-theme-overviews/s2-2-2-topic-2-permutation.pdf",
              "note": "排列"
            }
          ]
        }
      ]
    },
    "s2-2-2-main-theme-combination": {
      "id": "s2-2-2-main-theme-combination",
      "title": "組合",
      "updatedAt": "2026-05-08T09:45:09+08:00",
      "variants": [
        {
          "id": "editable",
          "label": "可修改版",
          "sections": [
            {
              "type": "table",
              "headers": [
                "重點",
                "整理"
              ],
              "rows": [
                [
                  "組合不在乎順序",
                  "只看選到哪些物件，不看排法。"
                ],
                [
                  "從 $n$ 個不同物中取 $k$ 個",
                  "\\(C_k^n=\\frac{n!}{k!(n-k)!}\\)。"
                ],
                [
                  "和排列的關係",
                  "\\(C_k^n=\\frac{P_k^n}{k!}\\)，因為同一組元素有 \\(k!\\) 種排法。"
                ],
                [
                  "基本值",
                  "\\(C_0^n=1\\)，\\(C_n^n=1\\)。"
                ],
                [
                  "對稱性",
                  "\\(C_k^n=C_{n-k}^n\\)，因為選 \\(k\\) 個和不選那 \\(n-k\\) 個本質相同。"
                ],
                [
                  "帕斯卡公式",
                  "\\(C_k^n=C_k^{n-1}+C_{k-1}^{n-1}\\)。"
                ],
                [
                  "所有子集個數",
                  "\\(n\\) 個不同元素的子集總數是 \\(2^n\\)。"
                ],
                [
                  "重複組合",
                  "允許重複選取時，\\(H_m^n=C_{m+n-1}^m\\)。"
                ],
                [
                  "方程式解的連結",
                  "非負整數解 \\(x_1+\\cdots+x_n=m\\) 的個數也是 \\(C_{m+n-1}^m\\)。"
                ],
                [
                  "幾何題也常用組合",
                  "點連成線、選三點成三角形、凸多邊形對角線數量，都常落在組合公式上。"
                ],
                [
                  "函數個數觀念",
                  "若從 \\(n\\) 元集合映到 \\(m\\) 元集合，函數總數是 \\(m^n\\)。"
                ],
                [
                  "解題提醒",
                  "如果選完之後不會再排位置，通常就不是排列而是組合。"
                ]
              ]
            }
          ]
        },
        {
          "id": "original",
          "label": "原稿版",
          "sections": [
            {
              "type": "pdf-page",
              "src": "exports/main-theme-overviews/s2-2-2-topic-3-combination.pdf",
              "note": "組合"
            }
          ]
        }
      ]
    },
    "s2-2-3-main-theme-binomial-theorem": {
      "id": "s2-2-3-main-theme-binomial-theorem",
      "title": "二項式定理",
      "updatedAt": "2026-05-08T09:45:09+08:00",
      "variants": [
        {
          "id": "editable",
          "label": "可修改版",
          "sections": [
            {
              "type": "table",
              "headers": [
                "重點",
                "整理"
              ],
              "rows": [
                [
                  "基本公式",
                  "\\((x+y)^n=\\sum_{r=0}^{n}C_r^n x^{n-r}y^r\\)。"
                ],
                [
                  "第 $r+1$ 項怎麼看",
                  "一般項是 \\(T_{r+1}=C_r^n x^{n-r}y^r\\)。"
                ],
                [
                  "總共有幾項",
                  "從 \\(r=0\\) 到 \\(r=n\\)，所以共有 \\(n+1\\) 項。"
                ],
                [
                  "中間係數最大時最常考",
                  "若 \\(n\\) 是偶數，最大係數在正中間；若 \\(n\\) 是奇數，會有兩個一樣大的中間係數。"
                ],
                [
                  "係數和",
                  "把 \\(x=y=1\\) 代入，可得 \\(\\sum_{r=0}^{n}C_r^n=2^n\\)。"
                ],
                [
                  "交錯和",
                  "把 \\(x=1,y=-1\\) 代入，可得 \\(\\sum_{r=0}^{n}(-1)^rC_r^n=0\\)。"
                ],
                [
                  "奇偶項和",
                  "把 \\((1+1)^n\\) 和 \\((1-1)^n\\) 配合使用，可得奇數項和、偶數項和都等於 \\(2^{n-1}\\)。"
                ],
                [
                  "平方和公式",
                  "\\(\\sum_{r=0}^{n}(C_r^n)^2=C_n^{2n}\\)。"
                ],
                [
                  "和組合的關係很深",
                  "很多組合恆等式都能靠展開 \\((1+x)^n\\) 或比較係數得到。"
                ],
                [
                  "解題提醒",
                  "若題目問某一項係數、常數項、指定次方項，先寫一般項最有效率。"
                ]
              ]
            }
          ]
        },
        {
          "id": "original",
          "label": "原稿版",
          "sections": [
            {
              "type": "pdf-page",
              "src": "exports/main-theme-overviews/s2-2-3-topic-1-binomial-theorem.pdf",
              "note": "二項式定理"
            }
          ]
        }
      ]
    },
