                [
                  "一元一次式",
                  "只含一個未知數，而且未知數次方是 1 的式子，叫做一元一次式。"
                ],
                [
                  "項",
                  "式子中用加號隔開後看到的每一部分，都可以視為一個項。"
                ],
                [
                  "同類項",
                  "字母相同、次方也相同的項，才叫同類項。"
                ],
                [
                  "常數項",
                  "像 \\(3\\) 和 \\(-5\\) 這種不含字母的項，也彼此是同類項。"
                ],
                [
                  "合併原則",
                  "只有同類項才能合併，例如 \\(6x-2x=4x\\)，但 \\(6x+3\\) 不能直接合成 \\(9x\\)。"
                ]
