    "j2-1-1-main-theme-two-variable-expression-and-equation": {
      "id": "j2-1-1-main-theme-two-variable-expression-and-equation",
      "title": "二元一次式與二元一次方程式",
      "updatedAt": "2026-05-13T06:03:54+08:00",
      "variants": [
        {
          "id": "editable",
          "label": "可修改版",
          "sections": [
            {
              "type": "table",
              "headers": [
                "重點",
                "整理"
              ],
              "rows": [
                [
                  "二元一次式的定義",
                  "只含兩個未知數，且每個未知數的次方都是 \\(1\\) 的式子，叫做二元一次式。"
                ],
                [
                  "常見形式",
                  "二元一次式常寫成 \\(ax+by+c\\)，二元一次方程式常寫成 \\(ax+by=c\\)。"
                ],
                [
                  "係數與常數項",
                  "在 \\(ax+by+c\\) 中，\\(a\\)、\\(b\\) 是係數，\\(c\\) 是常數項。"
                ],
                [
                  "什麼不算二元一次式",
                  "像 \\(x^2+y\\)、\\(xy+3\\) 都不是，因為前者有二次，後者有兩個字母相乘。"
                ],
                [
                  "方程式比式子多一個等號",
                  "像 \\(8x+15y+80=140\\) 是方程式；若沒有等號，就只是表示數量關係的式子。"
                ],
                [
                  "名稱要分清楚",
                  "式子是用來表示關係，方程式是用來表達左右相等的條件。"
                ]
              ]
            }
          ]
        },
        {
          "id": "original",
          "label": "原稿版",
          "sections": [
            {
              "type": "pdf-page",
              "src": "exports/main-theme-overviews/j2-1-1-topic-2-two-variable-expression-and-equation.pdf",
              "note": "二元一次式與二元一次方程式"
            }
          ]
        }
      ]
    },
