    "j2-1-2-main-theme-substitution-and-elimination-methods": {
      "id": "j2-1-2-main-theme-substitution-and-elimination-methods",
      "title": "解聯立方程式：代入消去法與加減消去法",
      "updatedAt": "2026-05-13T06:03:54+08:00",
      "variants": [
        {
          "id": "editable",
          "label": "可修改版",
          "sections": [
            {
              "type": "table",
              "headers": [
                "重點",
                "整理"
              ],
              "rows": [
                [
                  "核心想法",
                  "先消去一個未知數，把聯立方程式變成熟悉的一元一次方程式。"
                ],
                [
                  "代入消去法",
                  "先從其中一式解出一個未知數，再代回另一式。"
                ],
                [
                  "代入法適合情況",
                  "若某一式已很接近 \\(x=\\cdots\\) 或 \\(y=\\cdots\\)，或某個係數剛好是 \\(1\\)，通常先想代入。"
                ],
                [
                  "加減消去法",
                  "先把兩式調整成某個未知數係數相同或相反，再相加或相減把它消掉。"
                ],
                [
                  "加減法適合情況",
                  "若兩式係數好配，只要乘上適當倍數就能消去某個未知數，通常先想加減消去。"
                ],
                [
                  "求出第一個未知數後要代回",
                  "先找到一個未知數之後，還要代回其中一式，才能把另一個未知數也求出來。"
                ],
                [
                  "高斯消去法入門",
                  "高斯消去只是把係數整理成增廣矩陣後做消去，本質仍然是把兩個未知數消成一個。"
                ]
              ]
            }
          ]
        },
        {
          "id": "original",
          "label": "原稿版",
          "sections": [
            {
              "type": "pdf-page",
              "src": "exports/main-theme-overviews/j2-1-2-topic-2-substitution-and-elimination-methods.pdf",
              "note": "解聯立方程式：代入消去法與加減消去法"
            }
          ]
        }
      ]
    },
